---
const logos = [
  {
    src: "/brands/1.svg",
  },
  {
    src: "/brands/2.svg",
  },
  {
    src: "/brands/3.svg",
  },
  {
    src: "/brands/4.svg",
  },
  {
    src: "/brands/5.svg",
  },
  {
    src: "/brands/6.svg",
  },
  {
    src: "/brands/7.svg",
  },
  {
    src: "/brands/8.svg",
  },
  {
    src: "/brands/9.svg",
  },
  {
    src: "/brands/10.svg",
  },
];
---

<section class="bg-background">
  <div class="px-8 py-24 mx-auto max-w-7xl md:px-12 lg:px-20">
    <div
      class="items-center justify-center w-full overflow-hidden border grid grid-cols-2 border-border gap-px md:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5 bg-background rounded-3xl"
    >
      {
        logos.map((logo) => (
          <div class="p-8 hover:bg-linear-to-b bg-background group">
            <img
              class="aspect-2/1 overflow-hidden mx-auto rounded-lg object-contain object-center"
              src={logo.src}
              alt="#_"
              width="120"
              height="60"
            />
          </div>
        ))
      }
    </div>
  </div>
</section>
